package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevDept string = "   "
var WsRegHours decimal.Decimal = decimal.Zero
var WsOtHours decimal.Decimal = decimal.Zero
var WsGross decimal.Decimal = decimal.Zero
var WsDeptTotal decimal.Decimal = decimal.Zero
var WsDeptCount int64 = 0
var WsGrandTotal decimal.Decimal = decimal.Zero
var WsGrandCount int64 = 0
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var curRec EmpRec
var inputLines []string
var inputIdx int
var inputOpen bool

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func pow10(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func decPow10(n int) decimal.Decimal {
	return decimal.NewFromInt(10).Pow(decimal.NewFromInt(int64(n)))
}

func fitDecimal(d decimal.Decimal, intDigits, scale int) decimal.Decimal {
	if intDigits <= 0 {
		return d
	}
	mod := decPow10(intDigits)
	// keep low-order digits: remainder
	r := d.Mod(mod)
	return r
}

func fitInt(v int64, digits int) int64 {
	m := pow10(digits)
	if m == 0 {
		return v
	}
	// COBOL counts are non-negative; handle positive mod
	if v >= 0 {
		return v % m
	}
	// for negative, keep sign on low-order digits
	return -((-v) % m)
}

func parseNum(field string, scale int) decimal.Decimal {
	t := strings.TrimSpace(field)
	if t == "" {
		return decimal.Zero
	}
	// handle sign
	neg := false
	if strings.HasPrefix(t, "-") || strings.HasPrefix(t, "+") {
		if strings.HasPrefix(t, "-") {
			neg = true
		}
		t = t[1:]
		t = strings.TrimSpace(t)
		if t == "" {
			return decimal.Zero
		}
	}
	if strings.Contains(t, ".") {
		d, err := decimal.NewFromString((map[bool]string{true: "-", false: ""}[neg]) + t)
		if err != nil {
			return decimal.Zero
		}
		return d.Truncate(int32(scale))
	}
	// digits only: strip spaces inside?
	t = strings.ReplaceAll(t, " ", "0")
	// keep only digits
	var sb strings.Builder
	for _, ch := range t {
		if ch >= '0' && ch <= '9' {
			sb.WriteRune(ch)
		}
	}
	s := sb.String()
	if s == "" {
		return decimal.Zero
	}
	// parse as integer (may be large but fits)
	d, err := decimal.NewFromString(s)
	if err != nil {
		return decimal.Zero
	}
	d = d.Shift(int32(-scale))
	if neg {
		d = d.Neg()
	}
	return d
}

func formatEdited(value decimal.Decimal, picture string) string {
	// find dot
	dotPos := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	// count placeholders
	intPlaces := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intPlaces++
		}
	}
	fracPlaces := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' {
			fracPlaces++
		}
	}
	v := value.Truncate(int32(fracPlaces))
	av := v.Abs()
	scaled := av.Shift(int32(fracPlaces)).Truncate(0)
	// scaled fits int64 for our ranges; fallback to string if huge
	sScaled := scaled.StringFixed(0)
	// sScaled is non-negative integer string
	// ensure at least fracPlaces+1 digits? pad left
	need := fracPlaces + 1
	if len(sScaled) < need {
		sScaled = strings.Repeat("0", need-len(sScaled)) + sScaled
	}
	var intPartStr, fracPartStr string
	if fracPlaces > 0 {
		intPartStr = sScaled[:len(sScaled)-fracPlaces]
		fracPartStr = sScaled[len(sScaled)-fracPlaces:]
	} else {
		intPartStr = sScaled
		fracPartStr = ""
	}
	// drop high-order digits of integer part
	if len(intPartStr) > intPlaces {
		intPartStr = intPartStr[len(intPartStr)-intPlaces:]
	} else if len(intPartStr) < intPlaces {
		intPartStr = strings.Repeat("0", intPlaces-len(intPartStr)) + intPartStr
	}
	// integer digits array
	var out strings.Builder
	di := 0
	suppressed := true
	for _, ch := range intPic {
		switch ch {
		case 'Z':
			d := intPartStr[di]
			di++
			if suppressed && d == '0' {
				out.WriteByte(' ')
			} else {
				suppressed = false
				out.WriteByte(d)
			}
		case '9':
			d := intPartStr[di]
			di++
			suppressed = false
			out.WriteByte(d)
		case ',':
			if suppressed {
				out.WriteByte(' ')
			} else {
				out.WriteByte(',')
			}
		default:
			out.WriteByte(byte(ch))
		}
	}
	if dotPos >= 0 {
		out.WriteByte('.')
		fi := 0
		// fracPartStr length == fracPlaces
		for _, ch := range fracPic {
			switch ch {
			case 'Z', '9':
				var d byte
				if fi < len(fracPartStr) {
					d = fracPartStr[fi]
				} else {
					d = '0'
				}
				fi++
				out.WriteByte(d)
			default:
				out.WriteByte(byte(ch))
			}
		}
	}
	return out.String()
}

func formatCount(v int64, digits int) string {
	vm := fitInt(v, digits)
	if vm < 0 {
		vm = -vm // pictures unsigned; show absolute zero-padded
	}
	s := fmt.Sprintf("%d", vm)
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func display(s string) {
	fmt.Fprint(os.Stdout, s+"\n")
}

func MainPara() {
	openInput()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		DeptBreakPara()
	}
	closeInput()
	GrandPara()
}

func openInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		// missing file treated as empty? report error per spec? treat as empty to allow grand line
		// If file does not exist, consider no records.
		if os.IsNotExist(err) {
			inputLines = nil
			inputIdx = 0
			inputOpen = true
			return
		}
		fmt.Fprint(os.Stderr, err.Error()+"\n")
		os.Exit(1)
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)
	var lines []string
	for sc.Scan() {
		line := sc.Text()
		// strip trailing \r if present (Scanner strips \n but keeps \r? Actually ScanLines strips \r)
		if strings.HasSuffix(line, "\r") {
			line = strings.TrimSuffix(line, "\r")
		}
		lines = append(lines, line)
	}
	if err := sc.Err(); err != nil {
		fmt.Fprint(os.Stderr, err.Error()+"\n")
		os.Exit(1)
	}
	inputLines = lines
	inputIdx = 0
	inputOpen = true
}

func closeInput() {
	inputOpen = false
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	// pad/truncate to 17 bytes
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	curRec.ErId = line[0:5]
	curRec.ErDept = line[5:8]
	curRec.ErHours = parseNum(line[8:12], 1)
	curRec.ErRate = parseNum(line[12:17], 2)
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevDept = curRec.ErDept
		WsFirstFlag = "N"
	} else {
		if curRec.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = curRec.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	forty := decimal.NewFromInt(40)
	if curRec.ErHours.GreaterThan(forty) {
		WsRegHours = decimal.NewFromInt(40)
		// COMPUTE WS-OT-HOURS = ER-HOURS - 40 (truncated)
		WsOtHours = curRec.ErHours.Sub(forty).Truncate(1)
		WsOtHours = fitDecimal(WsOtHours, 3, 1)
	} else {
		WsRegHours = curRec.ErHours.Truncate(1)
		WsRegHours = fitDecimal(WsRegHours, 3, 1)
		WsOtHours = decimal.Zero
	}
	// COMPUTE WS-GROSS ROUNDED
	onePointFive := decimal.NewFromFloat(1.5)
	g := WsRegHours.Mul(curRec.ErRate).Add(WsOtHours.Mul(curRec.ErRate).Mul(onePointFive))
	g = g.Round(2)
	g = fitDecimal(g, 7, 2)
	WsGross = g
	WsDeptTotal = fitDecimal(WsDeptTotal.Add(WsGross).Truncate(2), 9, 2)
	WsDeptCount = fitInt(WsDeptCount+1, 3)
	WsGrandTotal = fitDecimal(WsGrandTotal.Add(WsGross).Truncate(2), 11, 2)
	WsGrandCount = fitInt(WsGrandCount+1, 5)
	WsHoursEd = formatEdited(curRec.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(curRec.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	display(curRec.ErId + " " + curRec.ErDept + " " + WsHoursEd + " " + WsRateEd + " " + WsGrossEd)
}

func DeptBreakPara() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	display("  DEPT " + WsPrevDept + " EMPLOYEES: " + formatCount(WsDeptCount, 3) + " TOTAL: " + WsDeptEd)
	WsDeptTotal = decimal.Zero
	WsDeptCount = 0
}

func GrandPara() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	display("GRAND TOTAL (" + formatCount(WsGrandCount, 5) + "): " + WsGrandEd)
}

func main() {
	MainPara()
}
